export function simulationCanvas(container,{snapshot,geometry=[],nx=12,ny=10,field='pressure',perspective=true,dfn=null}={}){const c=setupCanvas(container);function draw(){const{ctx}=c,[w,h]=c.size();ctx.clearRect(0,0,w,h);const raw=snapshot?.[field==='water'?'matrix_water_saturation':'matrix_pressure_mpa'],vals=raw?normalizeField(raw,nx,ny):[],lo=field==='water'?0:Math.min(...vals),hi=field==='water'?1:Math.max(...vals),sx=Math.min(w*.65,h*1.4),sy=sx*600/700;ctx.save();ctx.translate(w*.47,h*.48);if(perspective)ctx.transform(.88,-.19,.36,.58,0,0);ctx.translate(-sx/2,-sy/2);ctx.fillStyle='#142e3c';ctx.fillRect(6,12,sx,sy);if(vals.length){for(let j=0;j<ny;j++)for(let i=0;i<nx;i++){ctx.fillStyle=colorMap((vals[j*nx+i]-lo)/(hi-lo||1));ctx.fillRect(i*sx/nx,(ny-1-j)*sy/ny,sx/nx+.5,sy/ny+.5);ctx.strokeStyle='#98d7cb22';ctx.lineWidth=.5;ctx.strokeRect(i*sx/nx,(ny-1-j)*sy/ny,sx/nx,sy/ny)}}else{ctx.fillStyle='#153044';ctx.fillRect(0,0,sx,sy)}for(const f of dfn??geometry){ctx.beginPath();ctx.moveTo(f.x1/700*sx,(1-f.y1/600)*sy);ctx.lineTo(f.x2/700*sx,(1-f.y2/600)*sy);ctx.strokeStyle=dfn?'#75e3d4d9':'#d3f3e7b0';ctx.lineWidth=dfn?1.7:1.1;ctx.stroke()}
ctx.strokeStyle='#77adbf99';ctx.lineWidth=1;ctx.strokeRect(0,0,sx,sy);ctx.font='11px monospace';ctx.fillStyle='#a5c2d4';ctx.fillText('0',-12,sy+19);ctx.fillText('700 m（米）',sx-78,sy+20);ctx.save();ctx.rotate(-Math.PI/2);ctx.fillText('600 m（米）',-75,-13);ctx.restore();ctx.restore();ctx.fillStyle='#6d8fa6';ctx.font='9px monospace';ctx.fillText('MATRIX + FRACTURE / '+(dfn?'STOCHASTIC DFN':field==='water'?'WATER SATURATION':'PRESSURE FIELD'),17,h-17)}draw();const ro=new ResizeObserver(draw);ro.observe(container);return{update:o=>{snapshot=o.snapshot??snapshot;field=o.field??field;dfn=o.dfn??dfn;draw()},destroy:()=>{ro.disconnect();c.destroy()}};}
